// Vide les deux caches : sans ça, réautoriser un compte ne prenait effet
// qu'au bout de 5 minutes — le temps qu'on croie que le bouton ne marche pas.

// Dernier refus de capture, pour que le panneau puisse le DIRE. Un compte
// refusé en silence est indiscernable d'un compte jamais capté.
async function noterRefus(uid, domain, raison) {
  try {
    const cur = (await chrome.storage.local.get('vrmRefus')).vrmRefus || {};
    cur[String(uid)] = { at: Date.now(), domain, raison };
    await chrome.storage.local.set({ vrmRefus: bornerRegistre(cur, 30 * 864e5, 100) });
    // 5.197 : un compte refusé/supprimé n'est plus « déjà écrit » — réautorisé,
    // sa ligne repart tout de suite (pas dans 30 min).
    const m = (await chrome.storage.local.get('vrmCompteEcrit')).vrmCompteEcrit || {};
    if (m[String(uid)]) { delete m[String(uid)]; await chrome.storage.local.set({ vrmCompteEcrit: m }); }
  } catch (_) {}
}
async function oublierRefus(uid) {
  try {
    const cur = (await chrome.storage.local.get('vrmRefus')).vrmRefus || {};
    if (cur[String(uid)]) { delete cur[String(uid)]; await chrome.storage.local.set({ vrmRefus: cur }); }
  } catch (_) {}
}

async function captureDomain(domain) {
  const access = await getCookie(domain, 'access_token_web');
  if (!access) return null;
  const refresh = await getCookie(domain, 'refresh_token_web');
  const anon = await getCookie(domain, 'anon_id');
  const payload = jwtPayload(access);
  const uid = payload && payload.account_id ? String(payload.account_id) : null;
  if (!uid) return null;
  // Compte supprimé définitivement : on ne le re-capte pas et on efface une
  // éventuelle ligne restante, puis on s'arrête là.
  // ⚠️ SAUF s'il a été RÉAUTORISÉ explicitement (tri-état ci-dessus) : sinon la
  // suppression est un aller sans retour, et rebrancher un compte devient
  // impossible depuis Chrome — silencieusement.
  // ⚠️ ON N'EFFACE QUE SI ON SAIT. `null` veut dire « je n'ai pas pu lire » :
  //    agir dessus reviendrait à supprimer les jetons d'un compte vivant sur
  //    une simple coupure. Dans le doute, on ne touche à rien — le compte sera
  //    re-capté une fois de trop au pire, ce qui se répare d'un clic.
  const _noirs = await blockedAccounts();
  const _rallumes = await unblockedAccounts();
  if (_noirs && _rallumes && _noirs.has(uid) && !_rallumes.has(uid)) {
    { const moi = await utilisateurVrm(); if (moi) { try { await fetch(`${SUPABASE_URL}/rest/v1/vinted_accounts?vinted_user_id=eq.${encodeURIComponent(uid)}&owner=eq.${encodeURIComponent(moi)}`, { method: 'DELETE', headers: await sbHeaders(), signal: signalDelai(SB_DELAI_ECRITURE_MS) }); } catch (_) {} } }
    await noterRefus(uid, domain, 'supprime');
    logActivity(`⛔ Compte ${uid} ignoré (supprimé définitivement) — réautorise-le dans « Mes comptes »`);
    return null;
  }
  // 5.191 : « Non, ignorer ce compte » dans la carte — ses jetons ne partent
  // pas (on n'efface rien : c'est un choix de CE Chrome, réversible d'un clic).
  if (await compteRefuse(uid)) { await noterRefus(uid, domain, 'refuse'); return null; }
  await oublierRefus(uid);
  const row = {
    vinted_user_id: uid,
    domain,
    access_token: access,
    refresh_token: refresh || null,
    anon_id: anon || null,
    updated_at: new Date().toISOString(),
  };
  if (lastCsrfByDomain[domain]) row.csrf_token = lastCsrfByDomain[domain];
  // ⚠️⚠️ 20 octobre (5.197) — UNE ÉCRITURE PAR CHANGEMENT, PAS PAR REQUÊTE.
  //    Mesuré en production (journaux du 20 octobre) : jusqu'à 90 écritures de
  //    `vinted_accounts` PAR MINUTE, 687 en 73 min. Chaque requête de la page
  //    Vinted portant un `x-csrf-token` envoie un message `csrf` → ici → la
  //    ligne entière réécrite, jetons identiques. On n'écrit que si les jetons
  //    (ou le csrf) ont CHANGÉ, ou une fois toutes les 30 min au plus.
  //    L'empreinte vit dans `chrome.storage.local` (§4.9) ; perdue, elle ne
  //    coûte qu'une écriture de plus. Elle n'est posée qu'après une écriture
  //    RÉUSSIE : un refus de la base fait réessayer à la requête suivante.
  const sig = empreinteCompte(row);
  if (await compteDejaEcrit(uid, sig)) { noterDiag('compte_inchange'); return uid; }
  // 5.331 : jamais écrit depuis CE navigateur ⇒ première écriture de ce compte.
  const premiere = !(await compteDejaConnuIci(uid));
  _refusComptes.delete(uid);
  let ok = await supabaseUpsert('vinted_accounts', [row], 'vinted_user_id');
  // 5.332 (migration 029) : un compte NEUF ne se crée plus par l'API de la base.
  // Refus « preuve » (ou « unicité » de la 023) ⇒ la route serveur vérifie le
  // jeton chez Vinted et range la ligne. Avant la 029, l'upsert passe : rien ne
  // change et la route n'est jamais appelée.
  const refus = _refusComptes.get(uid) || '';
  _refusComptes.delete(uid);
  if (ok === false && (refus === 'preuve' || refus === 'unicite')) ok = await lierCompteParServeur(row);
  if (ok !== false) await noterCompteEcrit(uid, sig);
  if (ok === true) signalerCompteRelie('vinted', uid, premiere);
  return uid;
}

// ══ RELIER UN COMPTE VINTED NEUF PAR LE SERVEUR (5.332, défaut #5) ═══════════
// Décision de Julien (9 nov.) : un compte Vinted ne se relie qu'après PREUVE.
// `POST vrm.center/api/vinted-connect { source:'extension', … }` avec la session
// VRM : le serveur relit le jeton chez Vinted (`/api/v2/users/current`), vérifie
// qu'aucun AUTRE compte VRM ne porte ce compte, puis range la ligne (clé de
// service). Le corps ne porte QUE ce que l'extension rangeait déjà elle-même en
// base (les jetons du cookie de l'onglet). Le serveur ne renouvelle jamais le
// jeton (l'onglet resterait connecté avec un refresh_token consommé).
//   · une seule tentative par compte et par délai (`vrmLiaisonServeur`, §4.9) :
//     15 min après un « pas su », 1 h après un refus de Vinted, 24 h après un
//     « déjà relié à un autre compte VRM » (dit dans le journal d'activité) ;
//   · sans session VRM ⇒ aucun appel, rien noté comme refus (5.328).
// Rend true (rangé) ou false.
const LIAISON_URL = 'https://vrm.center/api/vinted-connect';
const LIAISON_ATTENTE_MS = { deja_relie: 24 * 3600000, refuse: 3600000, abonnement: 3600000, identifiant: 24 * 3600000, jeton_expire: 5 * 60000 };
const LIAISON_ATTENTE_DEFAUT_MS = 15 * 60000;
async function lierCompteParServeur(row) {
  const uid = String((row && row.vinted_user_id) || '');
  if (!/^[0-9]{1,20}$/.test(uid) || !row.access_token) return false;
  let memo = {};
  try { memo = (await chrome.storage.local.get('vrmLiaisonServeur')).vrmLiaisonServeur || {}; } catch (_) { return false; }
  const e = memo[uid];
  if (e && Date.now() < Number(e.prochain || 0)) { noterDiag('liaison_serveur_attente'); return false; }
  const s = await authToken();
  if (!(s && s.access_token && s.user_id)) return sessionAbsente();
  let status = 0, json = null;
  try {
    const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 20000);
    const r = await fetch(LIAISON_URL, {
      method: 'POST', signal: ctrl.signal,
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${s.access_token}` },
      body: JSON.stringify({ source: 'extension', accessToken: row.access_token, refreshToken: row.refresh_token || '', anonId: row.anon_id || '', csrfToken: row.csrf_token || '', domain: row.domain || 'www.vinted.fr' }),
    });
    clearTimeout(t);
    status = r.status;
    try { json = await r.json(); } catch (_) { json = null; }
  } catch (_) { status = 0; }
  const ok = status === 200 && !!(json && json.ok === true && json.account && String(json.account.vinted_user_id) === uid);
  try {
    const m = (await chrome.storage.local.get('vrmLiaisonServeur')).vrmLiaisonServeur || {};
    if (ok) delete m[uid];
    else {
      const raison = (json && typeof json.raison === 'string' && /^[a-z_]{1,30}$/.test(json.raison)) ? json.raison : (status ? `http_${status}` : 'reseau');
      m[uid] = { at: Date.now(), prochain: Date.now() + (LIAISON_ATTENTE_MS[raison] || LIAISON_ATTENTE_DEFAUT_MS), raison };
    }
    await chrome.storage.local.set({ vrmLiaisonServeur: m });
  } catch (_) {}
  if (ok) {
    noterDiag('liaison_serveur_ok');
    logActivity(`✅ Compte Vinted ${(json.account && json.account.login) || uid} relié à VRM (vérifié chez Vinted)`);
    return true;
  }
  const raison = json && json.raison;
  noterDiag(`liaison_serveur_${raison || (status ? 'http_' + status : 'reseau')}`);
  if (raison === 'deja_relie') logActivity(`⛔ Compte Vinted ${uid} : déjà relié à un autre compte VRM — contacte le support`);
  return false;
}

const COMPTE_REECRIT_MS = 30 * 60 * 1000;
// Empreinte courte (FNV-1a 32 bits) : on ne garde JAMAIS un jeton en clair
// dans le stockage de l'extension pour cette comparaison.
function empreinteCompte(row) {
  const s = [row.vinted_user_id, row.domain, row.access_token, row.refresh_token, row.anon_id, row.csrf_token || ''].join('|');
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16) + ':' + s.length;
}
async function compteDejaEcrit(uid, sig) {
  try {
    const m = (await chrome.storage.local.get('vrmCompteEcrit')).vrmCompteEcrit || {};
    const e = m[String(uid)];
    return !!(e && e.sig === sig && Date.now() - Number(e.at || 0) < COMPTE_REECRIT_MS);
  } catch (_) { return false; }                    // pas su : on écrit (comme avant)
}
// Une entrée (même ancienne) dans `vrmCompteEcrit` : ce Chrome a déjà écrit ce
// compte. Pas su (stockage illisible) ⇒ « connu » : on ne signale rien sur un doute.
async function compteDejaConnuIci(uid) {
  try {
    const m = (await chrome.storage.local.get('vrmCompteEcrit')).vrmCompteEcrit || {};
    return !!m[String(uid)];
  } catch (_) { return true; }
}

// ══ « shop_x EST RELIÉ À VRM » TOUT DE SUITE (5.331, 9 nov.) ══════════════════
// L'extension écrit les comptes DIRECTEMENT en base (`vinted_accounts`,
// `lbc_accounts`, `vc_session`) : sans app VRM ouverte, le serveur ne voyait un
// compte neuf qu'au cron du matin ou du soir (passation 2026-11-08-compte-relie,
// « Signal qui manque côté extension »). Après la PREMIÈRE écriture réussie d'un
// compte, l'extension prévient `POST vrm.center/api/push { action:'comptes' }`
// avec la session VRM : le corps ne dit RIEN (ni compte, ni nom) — la route relit
// tout au nom du vendeur de la session et décide (point de départ, une fois par
// compte, famille « Nouveau compte relié » — `api/_lib/compte-relie.js`).
//   · une fois par compte : `vrmComptesSignales` ({ 'vinted:222': { at, fait } })
//     dans `chrome.storage.local` (§4.9) ;
//   · sans session VRM ⇒ AUCUN appel (le signal attend, 24 h au plus) ;
//   · réseau, 5xx, 401, 429 ⇒ gardé, retenté à la prochaine écriture d'un compte ;
//     un autre 4xx (refus jugé) ⇒ oublié ; 2xx ⇒ fait, plus jamais rappelé ;
//   · un seul appel couvre tous les comptes en attente (la route relit tout).
// eBay n'est pas ici : c'est la route eBay (OAuth) qui écrit `ebay_comptes`.
const COMPTE_PUSH_URL = 'https://vrm.center/api/push';
const COMPTE_PUSH_MAX_MS = 24 * 3600000;
const RE_CLE_COMPTE_PUSH = /^(vinted|leboncoin|vestiaire):[\w:.-]{1,80}$/;
let _chaineComptePush = Promise.resolve();
function unComptePushALaFois(fn) {
  const suite = _chaineComptePush.then(() => fn(), () => fn());
  _chaineComptePush = suite.then(() => {}, () => {});
  return suite;
}
// `premiere` : la ligne de CE compte n'existait pas avant cette écriture.
// Rend une promesse (les audits l'attendent ; l'appelant n'a pas à le faire).
function signalerCompteRelie(plateforme, id, premiere) {
  if (premiere) marquerConnexionCapte(plateforme, id).catch(() => {});   // 5.377 : « Compte relié · … »
  return unComptePushALaFois(async () => {
    try {
      const cle = `${plateforme}:${String(id == null ? '' : id)}`;
      if (!RE_CLE_COMPTE_PUSH.test(cle)) return 0;
      const m = (await chrome.storage.local.get('vrmComptesSignales')).vrmComptesSignales || {};
      if (premiere && !m[cle]) { m[cle] = { at: Date.now(), fait: false }; await chrome.storage.local.set({ vrmComptesSignales: m }); }
    } catch (_) { return 0; }
    return envoyerComptesSignalesUn();
  });
}
function envoyerComptesSignales() { return unComptePushALaFois(envoyerComptesSignalesUn); }
async function envoyerComptesSignalesUn() {
  try {
    const m = (await chrome.storage.local.get('vrmComptesSignales')).vrmComptesSignales || {};
    const now = Date.now();
    let change = false;
    for (const k of Object.keys(m)) {
      const e = m[k] || {};
      if (!e.fait && now - Number(e.at || 0) > COMPTE_PUSH_MAX_MS) { delete m[k]; change = true; }
    }
    const enAttente = Object.keys(m).filter((k) => !(m[k] && m[k].fait));
    // Mémo borné : les 200 derniers « faits » suffisent (un compte relié se signale une fois).
    const faits = Object.keys(m).filter((k) => m[k] && m[k].fait).sort((a, b) => Number(m[b].at || 0) - Number(m[a].at || 0));
    for (const k of faits.slice(200)) { delete m[k]; change = true; }
    if (!enAttente.length) { if (change) await chrome.storage.local.set({ vrmComptesSignales: m }); return 0; }
    const s = await authToken();
    if (!s || !s.access_token) { noterDiag('compte_push_sans_session'); if (change) await chrome.storage.local.set({ vrmComptesSignales: m }); return 0; }
    let status = 0;
    try {
      const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 8000);
      const r = await fetch(COMPTE_PUSH_URL, { method: 'POST', signal: ctrl.signal,
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${s.access_token}` },
        body: JSON.stringify({ action: 'comptes' }) });
      clearTimeout(t); status = r.status;
    } catch (_) { status = 0; }
    const fini = (status >= 200 && status < 300) || (status >= 400 && status < 500 && status !== 401 && status !== 429);
    if (fini) { for (const k of enAttente) m[k] = { at: now, fait: true }; change = true; }
    noterDiag(status >= 200 && status < 300 ? 'compte_push_envoye' : `compte_push_${fini ? 'refus' : 'ko'}_${status || 'reseau'}`);
    if (change) await chrome.storage.local.set({ vrmComptesSignales: m });
    return fini && status < 300 ? enAttente.length : 0;
  } catch (_) { return 0; }
}

async function noterCompteEcrit(uid, sig) {
  try {
    const m = (await chrome.storage.local.get('vrmCompteEcrit')).vrmCompteEcrit || {};
    m[String(uid)] = { sig, at: Date.now() };
    await chrome.storage.local.set({ vrmCompteEcrit: m });
  } catch (_) {}
}

async function captureAllAccounts() {
  const results = [];
  for (const d of VINTED_DOMAINS) {
    const uid = await captureDomain(d);
    if (uid) results.push({ domain: d, uid });
  }
  try { chrome.storage.local.set({ lastSync: Date.now(), lastAccounts: results }); } catch (_) {}
  if (results.length) logActivity(`🔑 ${results.length} compte${results.length > 1 ? 's' : ''} synchronisé${results.length > 1 ? 's' : ''}`);
  return results;
}

// ── JOURNAL D'ACTIVITÉ (l'« interface quand je fais des actions ») ───────────
// Petit fil des dernières choses faites par l'extension, montré dans le panneau
// VRM. Anneau de 15 événements dans chrome.storage.local (léger, local).
async function logActivity(text) {
  try {
    const cur = (await chrome.storage.local.get('vrmActivity')).vrmActivity || [];
    cur.unshift({ t: Date.now(), text: String(text || '').slice(0, 90) });
    await chrome.storage.local.set({ vrmActivity: cur.slice(0, 15) });
  } catch (_) {}
}

// --- Capture passive des donnees ------------------------------------------

// Range une donnee moissonnee dans app_data sous une ligne dediee.
// ⚠️ POURQUOI CE COMPTEUR EXISTE. Vérifié en base : `harvest_*_item_*` = ZÉRO
// ligne, alors que `/api/v2/items/{id}` apparaît bien dans les chemins vus et que
// tout le code de capture est en place. Donc l'appel part et rien n'arrive : il y
// a une fuite quelque part entre inject.js et l'écriture. Trois sorties muettes
// sur ce chemin (pas de compte actif, corps non-JSON, type inconnu) — impossible
// de savoir laquelle sans mesurer. Ce compteur note CHAQUE passage et CHAQUE
// abandon, par type. Aucune donnée personnelle : des nombres.
// Conséquence concrète : sans fiche article, pas de description → « Republier »
// obligerait à tout retaper. C'est le vrai blocage de cette fonction.
// ⚠️⚠️ L'INSTRUMENTATION NE SURVIVAIT PAS AU SERVICE WORKER (2 septembre).
// `_diag.n` et `_rates` étaient des variables de MODULE, écrites en base au plus
// une fois par minute. Or Chrome tue un service worker MV3 après ~30 s
// d'inactivité : le tampon mourait donc AVANT le flush, et les compteurs comme
// les échantillons partaient avec lui.
// PREUVE DIRECTE EN BASE, pas une hypothèse : `recupererLabel` pose TROIS
// échantillons dans la même boucle (label_url, shipments/{id}, label_options),
// à quelques centaines de millisecondes d'intervalle. Le premier écrivait et
// consommait le quota d'une minute ; les deux suivants étaient jetés. En base,
// `rates` ne contient QUE `label_label_url` — jamais `label` ni
// `label_label_options`. C'est exactement pour ça qu'après trois sessions
// d'instrumentation on ne connaissait toujours la forme d'AUCUNE de ces
// réponses : on ne pouvait pas la capturer.
// Même dégât sur les compteurs : `label_url_trouve = 6` pour `label_envoye = 2`
// sans aucun compteur d'échec entre les deux — les deltas manquants n'ont jamais
// été flushés.
// ➡️ LE TAMPON VIT DÉSORMAIS DANS `chrome.storage.local` : local, gratuit, zéro
// égress, et il SURVIT à la mort du worker. Le throttle ne protège plus que
// l'écriture Supabase ; il ne peut plus rien perdre.
const DIAG_BUF = 'vrmDiagBuf';
let _diagChaine = Promise.resolve();   // sérialise les lecture-modification-écriture
let _diagFlushAt = 0;

// Toute modification du tampon passe par ici : deux appels concurrents feraient
// sinon un lire-modifier-écrire croisé et perdraient des incréments.
function majTampon(fn) {
  _diagChaine = _diagChaine.then(async () => {
    let buf = {};
    try { const s = await chrome.storage.local.get(DIAG_BUF); buf = (s && s[DIAG_BUF]) || {}; } catch (_) {}
    buf.n = buf.n || {}; buf.rates = buf.rates || {};
    fn(buf);
    try { await chrome.storage.local.set({ [DIAG_BUF]: buf }); } catch (_) {}
    // Le flux Supabase reste throttlé — mais s'il ne part pas, rien n'est perdu.
    if (Date.now() - _diagFlushAt < 60000) return;
    _diagFlushAt = Date.now();
    await viderTampon(buf);
  }).catch(() => {});
  return _diagChaine;
}

// Envoie le tampon en base et ne le vide QUE si l'écriture a abouti.
async function viderTampon(buf) {
  const aDesN = Object.keys(buf.n || {}).length, aDesR = Object.keys(buf.rates || {}).length;
  if (!aDesN && !aDesR) return;
  // ⚠️ LECTURE RATÉE ≠ LIGNE VIDE : rien n'est écrit (et le tampon local n'est
  //    PAS vidé : les compteurs repartiront au prochain tour).
  // (5.362 : la ligne de DIAGNOSTIC reste en lire-fusionner-réécrire — la passer en
  //  comparer-et-échanger, comme `seen_urls` et les statuts d'offres, est noté dans
  //  le récit ; deux Chrome peuvent encore s'y perdre quelques compteurs, rien d'autre.)
  const rows = await sbGet('app_data?id=eq.panel_diag_capture&select=data');
  if (rows === null) return;
  const ver = (() => { try { return String(chrome.runtime.getManifest().version || ''); } catch (_) { return ''; } })();
  const okDiag = await supabaseUpsert('app_data', [{ id: 'panel_diag_capture', data: ((d) => {
    const tout = Object.assign({}, d || {}); delete tout.rev;
    const n = { ...(tout.n || {}) };
    for (const k in buf.n) n[k] = (n[k] || 0) + buf.n[k];
    // 5.362 (moyenne 49) : les anciens échantillons perdent leur `tete` (un morceau du corps).
    const rates = {};
    for (const [k, v] of Object.entries(Object.assign({}, tout.rates || {}, buf.rates || {}))) { if (v && typeof v === 'object') { const c = Object.assign({}, v); delete c.tete; rates[k] = c; } }
    return { ...tout, n, rates, majAt: new Date().toISOString(),
      ...(ver ? { ver, verAt: new Date().toISOString() } : {}), verCode: CODE_VERSION };
  })((rows[0] && rows[0].data) || {}) }], 'id');
  if (okDiag === false) return;
  buf.n = {}; buf.rates = {};
  try { await chrome.storage.local.set({ [DIAG_BUF]: buf }); } catch (_) {}
}

// Un exemplaire par type, écrasé à chaque fois (pas d'accumulation).
function formeEchantillon(body) {
  const t = String(body == null ? '' : body).trim();
  if (!t) return 'vide';
  if (/^</.test(t)) return 'html';
  try {
    const j = JSON.parse(t);
    if (Array.isArray(j)) return 'liste';
    if (j && typeof j === 'object') return 'objet:' + Object.keys(j).slice(0, 12).map((k) => String(k).replace(/[^A-Za-z0-9_]/g, '').slice(0, 30)).join(',');
    return typeof j;
  } catch (_) { return 'illisible'; }
}
async function echantillonRate(type, id, body) {
  const t = String(type || 'inconnu');
  return majTampon((buf) => {
    buf.rates[t] = {
      id: String(id == null ? '' : id).slice(0, 40),
      taille: body == null ? null : String(body).length,
      type: typeof body,
      // ⚠️ 5.362 (revue, moyenne 49) : plus AUCUN morceau du corps (les 160 premiers
      //    caractères pouvaient porter le texte d'un message, une adresse). La FORME
      //    seulement : JSON ou non, et les noms de clés du premier niveau.
      forme: formeEchantillon(body),
      at: new Date().toISOString(),
    };
  });
}

// Les chemins de clés d'une réponse qui évoquent un boost (push_up, bump,
// spotlight, promotion…) — noms seulement, profondeur bornée.
function clesDeBoost(obj) {
  const out = [];
  const marche = (o, chemin, prof) => {
    if (!o || typeof o !== 'object' || prof > 4 || out.length >= 40) return;
    const cles = Array.isArray(o) ? (o.length ? ['0'] : []) : Object.keys(o);
    for (const k of cles) {
      const c = chemin ? chemin + '.' + k : k;
      if (/push_?up|bump|spotlight|promot|boost|vas_|visibil/i.test(k)) out.push(c);
      marche(o[k], c, prof + 1);
    }
  };
  try { marche(obj, '', 0); } catch (_) {}
  return out;
}
// 5.371 : les 30 dernières ÉTIQUETTES notées, datées (`vrmDiagRecents`, ce navigateur)
// — ce que « Envoyer un rapport » joint (étiquettes techniques, jamais une donnée).
let _diagRecents = Promise.resolve();
// 5.409 (19 nov., chantier colis-achat-auto) — LE DIAGNOSTIC DES LECTURES, PAR NAVIGATEUR. `panel_diag_capture` est
// UNE ligne pour tous les navigateurs (cumul) : le 19 nov., celui resté en 5.273 la réécrivait et les compteurs des
// versions récentes (`suivi_plafond_heure`, refus de lecture) n'y étaient pas lisibles — la mesure n'a pas pu dire
// pourquoi le suivi n'était plus lu. Les clés des LECTURES (suivi, lectures refusées, rattrapages qui laissent la
// place, import) sont aussi comptées dans CE navigateur, par jour (aujourd'hui + hier), et publiées dans SA ligne
// `ext_appareil_{id}` (`diag`). Des compteurs seulement : aucun n°, aucun texte.
const DIAG_NAV = 'vrmDiagNav';
const RE_DIAG_NAV = /^(?:suivi_|lecture_|versement_laisse|versement_plafond|import_|lectures_)/;
function diagNavAjoute(etat, cle, jour) {
  const e = etat && typeof etat === 'object' ? etat : {};
  let auj = e.auj && e.auj.jour === jour ? e.auj : null, hier = e.hier || null;
  if (!auj) { hier = e.auj && e.auj.jour ? e.auj : hier; auj = { jour, n: {} }; }
  const n = Object.assign({}, auj.n);
  if (Object.keys(n).length < 80 || n[cle]) n[cle] = (n[cle] || 0) + 1;
  return { auj: { jour, n }, hier };
}
async function noterDiag(cle) {
  _diagRecents = _diagRecents.then(async () => {
    let l = []; try { l = (await chrome.storage.local.get('vrmDiagRecents')).vrmDiagRecents; } catch (_) {}
    l = Array.isArray(l) ? l : [];
    l.push({ k: String(cle).slice(0, 60), at: Date.now() });
    try { await chrome.storage.local.set({ vrmDiagRecents: l.slice(-30) }); } catch (_) {}
    if (RE_DIAG_NAV.test(String(cle))) {
      try {
        const g = (await chrome.storage.local.get(DIAG_NAV))[DIAG_NAV];
        await chrome.storage.local.set({ [DIAG_NAV]: diagNavAjoute(g, String(cle).slice(0, 60), new Date().toISOString().slice(0, 10)) });
      } catch (_) {}
    }
  }).catch(() => {});
  return majTampon((buf) => { buf.n[cle] = (buf.n[cle] || 0) + 1; });
}

// Le dressing qui arrive est-il au moins aussi riche que celui déjà en base ?
// Lecture ULTRA légère : on ne relit que le compteur `nItems` (un scalaire),
// jamais le payload — la leçon d'égress de §34 vaut aussi ici.
// ⚠️ LA MÊME RÈGLE, POUR TOUTE LISTE MOISSONNÉE. Elle ne protégeait que le
// dressing. Or les commandes et la boîte se font écraser exactement pareil :
// une réponse tronquée (page 1 seule, liste filtrée, session à moitié expirée)
// remplaçait une capture complète, et des ventes « disparaissaient » sans que
// personne ne touche à rien. Le compteur est lu EN SCALAIRE (`data->>nItems`),
// jamais le payload — la leçon d'égress de §34 vaut ici aussi.
const CLE_LISTE = { listings: 'items', orders_sold: 'my_orders', orders_purchased: 'my_orders', inbox: 'conversations' };
// ⚠️ CHAMPS STRUCTURELS — la dérive de forme QUI NE RENOMME PAS LA CLÉ DE LISTE.
// La clé de liste peut rester `items`/`my_orders` et un CHAMP INTÉRIEUR être
// renommé : c'est le vrai bug déjà vécu (§ `brand_title` vs `brand` — l'allègement
// gardait un champ qui n'existe plus, et TOUT le stock affichait « marque
// manquante » sans la moindre erreur). On vérifie donc que les champs qu'on LIT
// sont encore là.
// ⚠️ UNIQUEMENT des champs STRUCTURELS (présents quelle que soit la catégorie) :
// Julien veut que l'app serve aussi un reseller de livres ou de sacs — `brand` et
// `size` peuvent légitimement manquer à tout un stock, donc les exiger crierait au
// loup. `id`/`title`/`price`/`transaction_id` ne dépendent pas de ce qu'on vend.
const CHAMPS_CRITIQUES = {
  listings:         ['id', 'title', 'price'],
  orders_sold:      ['transaction_id', 'title'],
  orders_purchased: ['transaction_id', 'title'],
  inbox:            ['id'],
};
// ⚠️⚠️ 5.165 — « LISTE COMPLÈTE DEVENUE PLUS COURTE » N'EST PAS « PAGE PARTIELLE ».
//    Julien, 9 octobre : « je viens de supprimer beaucoup de paires et elles
//    sont encore marquées dans les annonces ». Une annonce SUPPRIMÉE disparaît
//    du dressing (mesuré : 10010415608 d'angeled92, absente de la lecture
//    suivante) — et un compte dont il supprime TOUT rend `items: []`,
//    `total_entries: 0`. `listePlusRiche` (total > 0 exigé) et `plein()`
//    refusaient ce vide POUR TOUJOURS : le compte restait figé sur ses
//    anciennes annonces, toutes affichées « en ligne » (prouvé au banc).
//    Ce qui sépare une liste complète d'une page partielle, c'est ce que la
//    moisson ACTIVE sait et qu'une page captée en passant ignore : elle a lu
//    TOUTES les pages, sans un échec, jusqu'à la dernière que Vinted annonce
//    (`opts.complet`). Elle fait alors foi — y compris vide —
//      · si Vinted donne un total, il doit être ATTEINT (sinon sa pagination se
//        contredit : 96 articles lus pour 150 annoncés, c'est une page qui
//        manque, et §4.2 reste vrai) ;
//      · sans total, une liste VIDE n'est jamais une preuve (§4.1).
//    ⚠️ La capture PASSIVE (`storeHarvest`) n'a jamais `complet` : une page 1
//    de 20 annonces n'écrase toujours pas un dressing de 61.
function dressingCompletFaitFoi(parsed, opts) {
  if (!(opts && opts.complet === true)) return false;
  const items = parsed && Array.isArray(parsed.items) ? parsed.items : null;
  if (!items) return false;
  const pg = parsed.pagination || {};
  const total = Number(pg.total_entries);
  if (pg.total_entries != null && pg.total_entries !== '' && isFinite(total)) return items.length >= total;
  return items.length > 0;
}
// ⚠️⚠️ REVUE DE LA 5.165 — « PAS SU » NE VAUT PAS « ON ÉCRIT » (§4.1, §4.2).
//    La lecture du compteur ratée (522, réseau, une réponse qui n'est pas un
//    tableau) rendait `true` : « on ne sait pas → on écrit ». Prouvé au banc
//    (lecture KO, écriture OK — le cas qui détruit) : la page 1 du dressing,
//    20 annonces sur 61, ÉCRASAIT la liste complète, et depuis la 5.165 avec un
//    `capturedAt` rajeuni — la liste tronquée se présentait comme fraîche et
//    complète. Trois états désormais : `true` on écrit · `false` plus pauvre ·
//    `null` PAS SU (on n'écrit pas ; l'appelant le compte à part). On n'écrit
//    sans comparer que sur une capture complète, ou quand la base dit qu'il n'y
//    a pas encore de ligne (ou une ligne sans compteur).
async function listePlusRiche(rowId, parsed, cle) {
  const n = ((parsed && parsed[cle]) || []).length;
  const total = Number(parsed && parsed.pagination && parsed.pagination.total_entries);
  if (isFinite(total) && total > 0 && n >= total) return true;   // capture complète : fait foi
  const passu = () => { noterDiag('ignore_partiel_lecture_ratee'); return null; };
  try {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/app_data?id=eq.${rowId}&select=n:data->>nItems`, { headers: await sbHeaders(), signal: signalDelai(SB_DELAI_LECTURE_MS) });
    if (!r.ok) return passu();                    // pas su : on n'écrase rien
    const j = await r.json();
    if (!Array.isArray(j)) return passu();        // un 522 Cloudflare rend du HTML
    if (!j.length) return true;                   // aucune ligne encore : on écrit
    const avant = Number(j[0] && j[0].n);
    if (j[0].n == null || !isFinite(avant)) return true;   // ancienne ligne sans compteur → on écrit
    return n >= avant;                            // jamais plus pauvre qu'avant
  } catch (_) { return passu(); }
}

// ══ LA BOÎTE DE RÉCEPTION SE FUSIONNE, ELLE NE SE COMPTE PAS (5.162) ═══════
// MESURÉ le 6 octobre sur sa base : deux comptes avaient leur boîte figée sur
// une page ANCIENNE — `24602614` sur la page 5 (dernière conversation captée le
// 27 juillet, dernière vente le 2 octobre), `3156028798` sur la page 3
// (25 août / 5 octobre). Cause : `listePlusRiche` ne compare que des NOMBRES.
// Quand il fait défiler sa messagerie, la page charge les pages 2…6 (50
// conversations chacune) et la plus profonde est rangée ; la page 1 fraîche
// (30 conversations, moisson active) est ensuite refusée comme « plus
// pauvre ». La boîte ne bougeait plus — et la messagerie de l'app non plus.
// ⇒ Pour la boîte, on FUSIONNE par identifiant de conversation :
//   · une réponse `current_page === 1` met à jour le HAUT de la liste (ses
//     conversations remplacent celles qu'on avait, non lues comprises) ;
//   · une page plus profonde ne fait que COMPLÉTER (une conversation absente
//     s'ajoute ; une présente n'est remplacée que si elle est plus récente) ;
//   · triée par `updated_at`, bornée aux 300 plus récentes ;
//   · même forme rangée `{ pagination, conversations }` pour tous les lecteurs.
// ⚠️ « Rien lu ne vaut pas rien » : si la ligne en base n'a pas pu être lue, on
//    n'écrit PAS (une page 1 seule écraserait les 300 conversations gardées —
//    la famille lire-fusionner-réécrire, `audit-fusion`). Et une réponse VIDE
//    n'est jamais une réponse (§4.1) : rien n'est écrit.
const INBOX_MAX = 300;
function pageDeInbox(p) {
  const pg = p && p.pagination;
  const n = Number(pg && (pg.current_page != null ? pg.current_page : pg.page));
  return isFinite(n) && n > 0 ? n : null;
}
const tsConversation = (c) => { const t = Date.parse((c && c.updated_at) || ''); return isNaN(t) ? 0 : t; };
function fusionnerInbox(avant, neuf) {
  const convsN = (neuf && Array.isArray(neuf.conversations)) ? neuf.conversations : [];
  const convsA = (avant && Array.isArray(avant.conversations)) ? avant.conversations : [];
  const haut = pageDeInbox(neuf) === 1;
  const par = new Map();
  for (const c of convsA) if (c && c.id != null) par.set(String(c.id), c);
  for (const c of convsN) {
    if (!c || c.id == null) continue;
    const k = String(c.id), a = par.get(k);
    if (haut || !a || tsConversation(c) > tsConversation(a)) par.set(k, c);
  }
  const conversations = [...par.values()].sort((x, y) => tsConversation(y) - tsConversation(x)).slice(0, INBOX_MAX);
  // La pagination dit d'où vient le HAUT de la liste : celle de la page 1 quand
  // elle arrive, sinon on garde celle qu'on avait (une page 5 ne la remplace pas).
  const pagination = (haut || !convsA.length || !(avant && avant.pagination))
    ? ((neuf && neuf.pagination) || (avant && avant.pagination) || null)
    : avant.pagination;
  return { pagination, conversations };
}
// Lit la boîte rangée et rend la fusion — `null` si la lecture a échoué
// (« pas su » : l'appelant n'écrit pas).
async function inboxFusionnee(rowId, neuf) {
  const rows = await sbGet(`app_data?id=eq.${encodeURIComponent(rowId)}&select=pg:data->payload->pagination,cv:data->payload->conversations`);
  if (rows === null) return null;
  const r0 = rows[0] || null;
  const avant = r0 ? { pagination: r0.pg || null, conversations: Array.isArray(r0.cv) ? r0.cv : [] } : null;
  return fusionnerInbox(avant, neuf);
}

// ══ LES VENTES ET LES ACHATS SE FUSIONNENT PAR N° DE TRANSACTION (5.323) ═════
// MESURÉ le 6 novembre (lecture seule, sa base) : une vente faite à 07:50 sur le
// compte 199082413 n'était pas dans VRM, alors que la visite du matin avait relu
// annonces, boîte et profil. Le compte a 2 162 ventes chez Vinted
// (`total_entries`), la ligne `harvest_199082413_orders_sold` en porte 2 000
// (`nItems`, la lecture de 20 pages × 100 de `inject.js`). Les autres lectures
// sont PLAFONNÉES plus bas : `rafraichirVentes` 8 × 40 = 320, la moisson de la
// page 10 × 100 = 1 000. `listePlusRiche` n'écrit que si la lecture est
// complète (n ≥ 2 162 — jamais atteint) ou au moins aussi longue que la base
// (2 000) ⇒ ces lectures étaient refusées EN SILENCE (« plus pauvre » :
// `ignore_partiel_orders_sold` = 1 129, `…_orders_purchased` = 1 071) — et
// comptées « lues » quand même. La vente du matin était dans la lecture… et
// jetée. La boîte a eu le même défaut, corrigé de la même façon (5.162).
// ⇒ Une lecture PARTIELLE des commandes (les pages récentes) se FUSIONNE dans
//   la liste rangée, par IDENTITÉ (`transaction_id`, §5 — jamais un titre) :
//   · une transaction lue maintenant remplace sa copie rangée (l'état le plus
//     frais est celui qu'on vient de lire) ;
//   · une transaction rangée hors de la fenêtre lue reste TELLE QUELLE — une
//     lecture partielle n'efface rien (loi 2) ; seule une lecture COMPLÈTE
//     (n ≥ total annoncé) remplace toute la liste, comme avant ;
//   · une transaction neuve s'ajoute (en tête si la lecture part de la page 1) ;
//   · une ligne sans `transaction_id` n'est pas une identité : elle n'est ni
//     ajoutée ni rapprochée ; une lecture où AUCUNE n'en porte n'écrit rien
//     (forme inconnue, dit : `ignore_commandes_sans_identite_<type>`) ;
//   · la ligne rangée illisible (base qui ne répond pas) ⇒ RIEN n'est écrit
//     (une fenêtre de 320 écraserait les 2 000 — `audit-fusion`).
// ⚠️ ÉGRESS (§4.4) : fusionner demande de relire la liste rangée (≈ 680 Ko pour
//    2 000 ventes). Une fenêtre IDENTIQUE à celle qu'on a soi-même fusionnée
//    il y a moins d'une heure n'est ni relue ni réécrite (`inchange`) ; au-delà
//    d'une heure elle est réécrite (la date de lecture rajeunit). Une vente
//    neuve, un statut qui bouge changent la fenêtre : écrits tout de suite.
//    Aucune requête Vinted de plus : ce sont les lectures qui partaient déjà.
const FENETRE_CMD = 'vrmFenetreCommandes';          // { [rowId]: { [empreinte]: ms } } (§4.9)
const FENETRE_CMD_VALIDITE_MS = 60 * 60 * 1000;
const FENETRE_CMD_MAX = 8;
// BEGIN COMMANDES PARTAGEES
// ══ LES VENTES ET LES ACHATS SE FUSIONNENT PAR N° DE TRANSACTION (5.323) ═════
// Récit : `docs/passation/2026-11-06-extension-5323.md`. Une lecture PARTIELLE
// des commandes (les pages récentes) se fusionne dans la liste rangée, par
// IDENTITÉ (`transaction_id`, §5 — jamais un titre) : une transaction relue
// remplace sa copie (l'état le plus frais), une transaction hors de la fenêtre
// reste telle quelle (loi 2), une neuve s'ajoute (en tête si la lecture part de
// la page 1). Une ligne sans `transaction_id` n'est ni ajoutée ni rapprochée.
// 5.326 (8 nov.) : CE TEXTE est la seule définition. Il est recopié tel quel
// dans `background.js` (bloc COMMANDES PARTAGEES) et importé par le serveur
// (`api/_lib/commandes-leger.js`) : l'extension et le serveur fusionnent avec
// la MÊME règle, au caractère près (`node scripts/sync-commandes.cjs --verifier`).
const cleTxCommande = (o) => { const t = o && o.transaction_id; return t == null || String(t).trim() === '' ? null : String(t); };
// La lecture part-elle du HAUT de la liste ? Les trois lecteurs partent de la
// page 1 et concatènent ; une page profonde SEULE (capture passive d'une page 3)
// ne vole pas le haut : ses transactions remplacent leur copie en place, une
// neuve va en queue.
function lectureDuHaut(neuf) {
  const pg = (neuf && neuf.pagination) || {};
  const cp = Number(pg.current_page != null ? pg.current_page : pg.page);
  const per = Number(pg.per_page);
  const n = ((neuf && neuf.my_orders) || []).length;
  return !(isFinite(cp) && cp > 1 && (!isFinite(per) || n <= per));
}
function fusionnerCommandes(avant, neuf) {
  const lus = neuf && Array.isArray(neuf.my_orders) ? neuf.my_orders : null;
  if (!lus) return null;
  const fen = new Map();
  for (const o of lus) { const k = cleTxCommande(o); if (k && !fen.has(k)) fen.set(k, o); }
  if (!fen.size) return null;                                   // aucune identité : forme inconnue
  const ranges = avant && Array.isArray(avant.my_orders) ? avant.my_orders : [];
  const dejaRangees = new Set(ranges.map(cleTxCommande).filter(Boolean));
  const neuves = [...fen.entries()].filter(([k]) => !dejaRangees.has(k)).map(([, o]) => o);
  const places = new Set(), corps = [];
  for (const o of ranges) {
    const k = cleTxCommande(o);
    if (k && fen.has(k)) { if (!places.has(k)) { places.add(k); corps.push(fen.get(k)); } }
    else corps.push(o);                                         // hors fenêtre (ou sans identité) : tel quel
  }
  const haut = lectureDuHaut(neuf);
  const my_orders = haut ? neuves.concat(corps) : corps.concat(neuves);
  const pagination = (haut || !(avant && avant.pagination)) ? ((neuf && neuf.pagination) || (avant && avant.pagination) || null) : avant.pagination;
  return Object.assign({}, avant && typeof avant === 'object' ? avant : {}, neuf, { pagination, my_orders });
}
// L'EMPREINTE D'UNE COMMANDE (5.326) : deux copies de la même commande (celle
// que l'extension vient de lire, celle rangée en base) ont la même empreinte si
// et seulement si leur CONTENU est le même. La base (jsonb) range les clés dans
// son propre ordre : on trie les clés à chaque niveau avant de hacher. Deux
// hachages de 32 bits (FNV-1a et djb2) : une collision sur la même transaction
// est hors de portée. Elle ne sert qu'à dire « déjà rangée telle quelle » — une
// empreinte inconnue fait ENVOYER la commande, jamais la deviner.
function canonCommande(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
  if (Array.isArray(v)) return '[' + v.map(canonCommande).join(',') + ']';
  return '{' + Object.keys(v).filter((k) => v[k] !== undefined).sort().map((k) => JSON.stringify(k) + ':' + canonCommande(v[k])).join(',') + '}';
}
function empreinteCommande(o) {
  const t = canonCommande(o);
  let a = 0x811c9dc5, b = 5381;
  for (let i = 0; i < t.length; i++) { const c = t.charCodeAt(i); a ^= c; a = Math.imul(a, 0x01000193) >>> 0; b = (Math.imul(b, 33) + c) >>> 0; }
  return a.toString(36) + b.toString(36);
}
// END COMMANDES PARTAGEES
// Empreinte d'une fenêtre lue (FNV-1a sur le texte allégé) — elle ne sort jamais du navigateur.
function empreinteFenetre(liste) {
  const t = JSON.stringify(liste || []);
  let h = 0x811c9dc5; for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return t.length.toString(36) + '.' + h.toString(36);
}
async function fenetreDejaRangee(rowId, emp) {
  try {
    const g = ((await chrome.storage.local.get(FENETRE_CMD))[FENETRE_CMD] || {})[rowId] || {};
    const at = Number(g[emp] || 0);
    return at > 0 && Date.now() - at < FENETRE_CMD_VALIDITE_MS;
  } catch (_) { return false; }                                 // pas su ⇒ on fusionne
}
async function noterFenetreRangee(rowId, emp) {
  try {
    const tout = (await chrome.storage.local.get(FENETRE_CMD))[FENETRE_CMD] || {};
    const g = Object.assign({}, tout[rowId] || {}, { [emp]: Date.now() });
    const garde = Object.entries(g).filter(([, at]) => Date.now() - Number(at) < FENETRE_CMD_VALIDITE_MS)
      .sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, FENETRE_CMD_MAX);
    tout[rowId] = Object.fromEntries(garde);
    await chrome.storage.local.set({ [FENETRE_CMD]: tout });
  } catch (_) {}
}
// Ce qu'il faut écrire pour une lecture de commandes (déjà ALLÉGÉE) :
//   { payload, emp }   la liste à ranger (complète telle quelle, ou fusionnée) ;
//   'inchange'         fenêtre identique, rangée par nous il y a moins d'1 h ;
//   'forme'            aucune identité dans la lecture (rien écrit, dit) ;
//   null               la base n'a pas répondu (pas su : rien écrit, dit).
async function commandesARanger(rowId, type, payload) {
  const lus = payload && Array.isArray(payload.my_orders) ? payload.my_orders : [];
  const total = Number(payload && payload.pagination && payload.pagination.total_entries);
  if (isFinite(total) && total > 0 && lus.length >= total) return { payload, emp: null };   // complète : fait foi
  const emp = empreinteFenetre(lus);
  if (await fenetreDejaRangee(rowId, emp)) { noterDiag(`fenetre_inchangee_${type}`); return 'inchange'; }
  const rows = await sbGet(`app_data?id=eq.${encodeURIComponent(rowId)}&select=pg:data->payload->pagination,mo:data->payload->my_orders`);
  if (rows === null || !Array.isArray(rows)) { noterDiag(`fusion_lecture_ratee_${type}`); return null; }
  const r0 = rows[0] || null;
  const avant = r0 ? { pagination: r0.pg || null, my_orders: Array.isArray(r0.mo) ? r0.mo : [] } : null;
  const f = fusionnerCommandes(avant, payload);
  if (!f) { noterDiag(`ignore_commandes_sans_identite_${type}`); return 'forme'; }
  noterDiag(`fusion_${type}`);
  return { payload: f, emp };
}

// ══ LES COMMANDES S'ENVOIENT LÉGÈRES (5.326, 8 nov.) ═════════════════════════
// Son iPhone (5.322) : « Dernier envoi refusé — la base n'a pas répondu, ça
// réessaie tout seul », en boucle, et les ventes de shop_cancale (~2 160) plus
// relues depuis le 6 nov. Fusionner (5.323) voulait dire RELIRE la ligne
// entière (≈ 0,9 Mo pour 2 000 ventes) puis la RÉÉCRIRE en entier (autant)
// pour y ranger 320 ventes : un `POST` de près d'un mégaoctet depuis un
// téléphone, que la suspension du service worker sur iOS coupe en route.
// ⇒ L'extension n'envoie plus que la FENÊTRE en abrégé (« n° : empreinte » par
//   commande, ≈ 25 octets), les `COMMANDES_TETE` commandes du haut en entier,
//   puis, sur demande, celles que la base n'a pas à l'identique (par lots de
//   `COMMANDES_LOT`). C'est `vrm.center` qui relit la ligne et la fusionne, avec
//   LA MÊME règle (bloc COMMANDES PARTAGEES ci-dessus, `api/_lib/commandes-leger.js`) ;
//   la ligne garde sa forme : aucun lecteur ne change.
// · « relues le … » n'avance que quand TOUTE la fenêtre est rangée (`complet`) ;
// · un refus, une coupure, la base qui ne répond pas ⇒ `null` : RIEN n'est
//   compté comme rangé, la carte le dit (code, famille, taille — 5.325) ;
// · la route absente (un `vrm.center` d'avant) ⇒ 'absent' : la voie d'avant
//   (relire + réécrire), pour ne rien perdre pendant le déploiement ;
// · une lecture COMPLÈTE et petite (≤ `COMMANDES_DIRECT_MAX`) ⇒ 'direct' : elle
//   s'écrit telle quelle, comme avant (≤ ~70 Ko, rien à fusionner).
// Aucune requête Vinted de plus, rien de plus dans le budget de lecture ni dans
// le plafond d'actions : seul le chemin vers la base change.
const COMMANDES_API = 'https://vrm.center/api/compte?mode=commandes';
const COMMANDES_TETE = 100;
const COMMANDES_LOT = 200;
const COMMANDES_TOURS_MAX = 12;
const COMMANDES_DIRECT_MAX = 150;
const RE_TX_LEGER = /^[0-9A-Za-z_-]{1,40}$/;
// Un envoi vers la route. Rend { j, octets } (réponse `ok`), 'absent' (route
// inconnue de ce `vrm.center`), ou `null` (refus, coupure, session : rien rangé,
// et le refus est noté comme ceux de `supabaseUpsert`, pour la carte).
async function appelCommandesServeur(envoi, famille) {
  let statut = 'reseau', octets = 0;
  try {
    for (let essai = 0; essai < 2; essai++) {
      const s = await authToken();
      if (!(s && s.access_token && s.user_id)) { statut = 'sans_session'; break; }
      const corps = JSON.stringify(envoi);
      octets = corps.length;
      const r = await fetch(COMMANDES_API, { method: 'POST', headers: { Authorization: `Bearer ${s.access_token}`, 'Content-Type': 'application/json' }, body: corps, ...(typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function' ? { signal: AbortSignal.timeout(30000) } : {}) });
      let j = null; try { j = await r.json(); } catch (_) { j = null; }
      if (r.ok && j && j.ok === true) { try { await effacerReculBase(); } catch (_) {} try { await effacerEchecsServeur(); } catch (_) {} return { j, octets }; }
      if (r.status === 404) return 'absent';
      statut = String(r.status || 'inconnu');
      // Un 401 : la session a pu vieillir — renouvelée UNE fois, puis rejoué
      // (rien n'a été écrit : la route refuse avant de lire).
      if (r.status === 401 && essai === 0) { const s2 = await renouvelerUneFois(); if (s2 && s2.access_token) continue; }
      break;
    }
  } catch (e) { statut = (e && e.statut) || 'reseau'; }
  // 5.328 : pas connecté ⇒ rien n'est parti, ce n'est pas un refus.
  if (statut === 'sans_session') { sessionAbsente(); return null; }
  try { noterDiag(`ecriture_ratee_${famille}_${statut}`); } catch (_) {}
  _statutDernierRefus = statut; _familleDernierRefus = famille; _octetsDernierRefus = octets;
  return null;
}
// Rend : 'ecrit' (fenêtre entière rangée) · 'partiel' (une partie rangée, la
// suite au prochain passage) · 'inchange' · 'forme' · `null` (rien rangé) ·
// 'absent' / 'direct' (la voie d'avant : `commandesARanger` + écriture entière).
async function commandesParServeur(uid, type, payload, domain) {
  const rowId = `harvest_${uid}_${type}`;
  const lus = payload && Array.isArray(payload.my_orders) ? payload.my_orders : [];
  const total = Number(payload && payload.pagination && payload.pagination.total_entries);
  const complet = isFinite(total) && total > 0 && lus.length >= total;
  if (complet && lus.length <= COMMANDES_DIRECT_MAX) return 'direct';
  const emp = empreinteFenetre(lus);
  if (!complet && await fenetreDejaRangee(rowId, emp)) { noterDiag(`fenetre_inchangee_${type}`); return 'inchange'; }
  const vus = new Set(), entrees = [];
  for (const o of lus) { const k = cleTxCommande(o); if (!k || vus.has(k)) continue; vus.add(k); entrees.push([k, empreinteCommande(o), o]); }
  if (!entrees.length) { noterDiag(`ignore_commandes_sans_identite_${type}`); return 'forme'; }
  if (entrees.some((e) => !RE_TX_LEGER.test(e[0]))) return 'absent';   // un n° hors forme : la voie d'avant
  const ae = ((resumeCommandes(type, { my_orders: lus }) || {}).txns) || [];
  let exclues = null;
  if (type === 'orders_sold') { try { const x = await transactionsQuiNeSExpedientPlus(uid); if (x) exclues = [...x]; } catch (_) {} }
  const base = { type, uid: String(uid), domain: domain || 'www.vinted.fr', luA: Date.now(), complet,
    pagination: (payload && payload.pagination) || null, fenetre: entrees.map((e) => e[0] + ':' + e[1]).join(','), ae, exclues };
  if (payload && payload.order_details_enabled !== undefined) base.order_details_enabled = payload.order_details_enabled;
  const parTx = new Map(entrees.map((e) => [e[0], e[2]]));
  const famille = `harvest_${type}`;
  let aEnvoyer = entrees.slice(0, COMMANDES_TETE).map((e) => e[2]);
  let ecritUneFois = false;
  for (let tour = 0; tour < COMMANDES_TOURS_MAX; tour++) {
    const r = await appelCommandesServeur(Object.assign({}, base, { commandes: aEnvoyer }), famille);
    if (r === 'absent') return ecritUneFois ? 'partiel' : 'absent';
    if (!r) {
      if (ecritUneFois) return 'partiel';
      // 5.327 : la N-ième coupure / erreur 5xx DE SUITE ⇒ la voie de secours (bornée).
      const n = await compterEchecServeur(_statutDernierRefus);
      return n >= SECOURS_APRES ? 'secours' : null;
    }
    if (r.j.ecrit) ecritUneFois = true;
    if (r.j.ecrit && r.j.complet) { await noterFenetreRangee(rowId, emp); noterDiag(`envoi_leger_${type}`); return 'ecrit'; }
    const manq = (Array.isArray(r.j.manquants) ? r.j.manquants : []).map(String).filter((k) => parTx.has(k));
    if (!manq.length) break;
    aEnvoyer = manq.slice(0, COMMANDES_LOT).map((k) => parTx.get(k));
  }
  // Tours épuisés (ou réponse sans suite) : ce qui est rangé l'est, la date ne bouge pas.
  _statutDernierRefus = 'incomplet'; _familleDernierRefus = famille; _octetsDernierRefus = 0;
  noterDiag(`envoi_leger_incomplet_${type}`);
  return ecritUneFois ? 'partiel' : null;
}
// ══ LA VOIE DE SECOURS (5.327, 8 nov.) ══════════════════════════════════════
// Deux jours sans rien sur son iPhone : vrm.center refusait le préalable CORS
// d'Orion, chaque envoi léger finissait en « réseau », et rien d'autre ne
// partait. ⇒ Après `SECOURS_APRES` échecs DE SUITE vers vrm.center (coupure ou
// 5xx — jamais un 4xx, qui est un refus durable que le secours ne réglerait
// pas), l'extension reprend l'ancienne voie DIRECTE vers la base (relire,
// fusionner par n° de transaction — `commandesARanger`, la règle de la 5.323 —,
// réécrire), MAIS BORNÉE : jamais plus de `SECOURS_MAX_OCTETS` d'un coup (la
// coupure d'un envoi de 1 Mo sur iOS est la panne d'origine). La taille se juge
// AVANT toute relecture, sur le compteur scalaire de la ligne (§4.2) ; une liste
// trop lourde n'est ni relue ni envoyée : RIEN n'est écrit (la ligne en base
// reste entière, « une capture partielle n'écrase jamais une complète »), et la
// carte du logo le DIT. Le premier succès de vrm.center remet tout à zéro.
const SECOURS_STORE = 'vrmSecoursCmd';
const SECOURS_APRES = 3;
const SECOURS_MAX_OCTETS = 256 * 1024;
const SECOURS_OCTETS_COMMANDE = 600;   // ≈ 540 o mesurés par commande allégée (2026-11-08-ventes-envoi-leger.md) + marge
const echecServeurPassager = (st) => st === 'reseau' || /^5\d\d$/.test(String(st == null ? '' : st));
async function compterEchecServeur(statut) {
  try {
    const cur = (await chrome.storage.local.get(SECOURS_STORE))[SECOURS_STORE] || {};
    const n = echecServeurPassager(statut) ? (Number(cur.n) || 0) + 1 : 0;
    await chrome.storage.local.set({ [SECOURS_STORE]: { n, at: Date.now(), statut: statut == null ? null : String(statut) } });
    return n;
  } catch (_) { return 0; }                                     // pas su ⇒ pas de secours
}
async function effacerEchecsServeur() {
  const s = await chrome.storage.local.get([SECOURS_STORE, 'vrmFlux']);
  if (Number((s[SECOURS_STORE] || {}).n) > 0) await chrome.storage.local.set({ [SECOURS_STORE]: { n: 0, at: Date.now() } });
  const fl = s.vrmFlux || {};
  if (fl.vinted && fl.vinted.secours) { delete fl.vinted.secours; await chrome.storage.local.set({ vrmFlux: fl }); }
}
async function noterSecours(etat, octets, type) {
  try {
    const fl = (await chrome.storage.local.get('vrmFlux')).vrmFlux || {};
    fl.vinted = Object.assign({}, fl.vinted || {}, { secours: { at: Date.now(), etat, octets: Number(octets) || 0, type } });
    await chrome.storage.local.set({ vrmFlux: fl });
  } catch (_) {}
}
// Rend ce que rend `commandesARanger` ({ payload, emp } · 'inchange' · 'forme' ·
// `null`), plus 'trop_lourd' (rien relu, rien écrit, dit).
async function commandesSecours(rowId, type, payload) {
  const lus = payload && Array.isArray(payload.my_orders) ? payload.my_orders : [];
  const total = Number(payload && payload.pagination && payload.pagination.total_entries);
  const complet = isFinite(total) && total > 0 && lus.length >= total;
  let estime = lus.length * SECOURS_OCTETS_COMMANDE;
  if (!complet) {
    const rows = await sbGet(`app_data?id=eq.${encodeURIComponent(rowId)}&select=n:data->>nItems`);
    if (rows === null || !Array.isArray(rows)) { noterDiag(`secours_lecture_ratee_${type}`); return null; }
    estime += (Number(rows[0] && rows[0].n) || 0) * SECOURS_OCTETS_COMMANDE;   // borne haute : base + lus
  }
  if (estime > SECOURS_MAX_OCTETS) { noterDiag(`secours_trop_lourd_${type}`); await noterSecours('trop_lourd', estime, type); return 'trop_lourd'; }
  const c = await commandesARanger(rowId, type, payload);
  if (!c || typeof c !== 'object') return c;
  const octets = JSON.stringify(c.payload).length;
  if (octets > SECOURS_MAX_OCTETS) { noterDiag(`secours_trop_lourd_${type}`); await noterSecours('trop_lourd', octets, type); return 'trop_lourd'; }
  noterDiag(`secours_${type}`);
  await noterSecours('envoi', octets, type);
  return c;
}

// Ce qui suit un envoi léger, sur les deux voies (passive, active) — les mêmes
// gestes que l'écriture directe : diagnostic, carte du logo, l'app qui relit.
// Rend ce que `storeHarvestRow` rend : 'ecrit' seulement si TOUTE la fenêtre est
// rangée ; une partie rangée n'est pas « rafraîchi » (la garde est relâchée,
// la suite part au prochain passage).
async function apresCommandesServeur(uid, type, lg, passif) {
  const ok = lg === 'ecrit';
  if (passif) noterDiag(`${ok ? 'ecrit' : 'ecriture_ratee'}_${type}`);
  if (lg !== null) notifierApp({ type: 'maj', quoi: type === 'orders_sold' ? 'ventes' : 'achats', uid: String(uid) });
  await noterFlux('vinted', ok);
  return ok ? 'ecrit' : 'ecriture-ratee';
}

// Les pages d'un même fil se réunissent par identité de message.
// BEGIN CONVERSATION PARTAGEE
function fusionnerConversation(avant, neuf) {
  const a = avant && (avant.conversation || avant), n = neuf && (neuf.conversation || neuf);
  if (!n || !Array.isArray(n.messages)) return null;
  if (a?.id != null && n.id != null && String(a.id) !== String(n.id)) return null;
  const messages = [], index = new Map();
  for (const m of [...(Array.isArray(a?.messages) ? a.messages : []), ...n.messages]) {
    if (!m || typeof m !== 'object') continue;
    const id = m.id ?? m.entity?.id;
    const cle = id == null || String(id).trim() === '' ? null : String(m.entity_type || '') + ':' + String(id);
    if (cle != null && index.has(cle)) {
      const i = index.get(cle), ancien = messages[i], entity = { ...(ancien.entity || {}), ...(m.entity || {}) };
      if (m.entity_type === 'offer_request_message') {
        // Identité immuable de l'offre : une contradiction ne se résout pas au hasard.
        for (const k of ['transaction_id', 'offer_request_id'])
          if (ancien.entity?.[k] != null && m.entity?.[k] != null && String(ancien.entity[k]) !== String(m.entity[k])) return null;
        // Une copie en attente ne réouvre jamais la même offre déjà traitée/précédente.
        if (entity.status === 10 && ([20,30].includes(ancien.entity?.status) || ancien.entity?.current === false || /expir|annul|cancel|retir/i.test(ancien.entity?.status_title || ''))) {
          for (const k of ['status','status_title','current']) entity[k] = ancien.entity?.[k];
        }
      }
      messages[i] = { ...ancien, ...m, ...(ancien.entity || m.entity ? {entity} : {}) };
    }
    else { if (cle != null) index.set(cle, messages.length); messages.push(m); }
  }
  const ts = m => { const v = m.created_at_ts ?? m.entity?.created_at_ts ?? m.created_at ?? m.entity?.created_at; const num = Number(v); return v == null ? 0 : Number.isFinite(num) ? (num < 1e12 ? num * 1000 : num) : (Date.parse(v) || 0); };
  messages.sort((x,y) => ts(x) - ts(y));
  const conversation = { ...(a || {}), ...n, messages };
  return neuf.conversation ? { ...neuf, conversation } : conversation;
}
// END CONVERSATION PARTAGEE

// L'id NUMÉRIQUE d'une réponse de conversation (`{conversation:{id}}` ou
// `{id}`), sinon null.
function idConversationReponse(parsed) {
  const c = parsed && (parsed.conversation || parsed);
  const v = c && c.id;
  if (Number.isSafeInteger(v) && v > 0) return String(v);
  if (typeof v === 'string' && /^[1-9]\d{0,19}$/.test(v)) return v;
  return null;
}

async function conversationFusionnee(rowId, neuf) {
  const rows = await sbGet(`app_data?id=eq.${encodeURIComponent(rowId)}&select=p:data->payload`);
  if (rows === null) return null;
  return fusionnerConversation(rows[0]?.p || null, neuf);
}

async function dressingPlusRiche(rowId, parsed) {
  const n = ((parsed && parsed.items) || []).length;
  const total = Number(parsed && parsed.pagination && parsed.pagination.total_entries);
  if (isFinite(total) && total > 0 && n >= total) return true;   // capture complète : fait foi
  try {
    const r = await fetch(`${SUPABASE_URL}/rest/v1/app_data?id=eq.${rowId}&select=n:data->>nItems`, { headers: await sbHeaders(), signal: signalDelai(SB_DELAI_LECTURE_MS) });
    if (!r.ok) return true;                       // on ne sait pas → on écrit
    const j = await r.json();
    const avant = Number(j[0] && j[0].n);
    if (!isFinite(avant)) return true;            // ancienne ligne sans compteur → on écrit
    return n >= avant;                            // jamais plus pauvre qu'avant
  } catch (_) { return true; }
}

// ── SENTINELLE DE FORME ──────────────────────────────────────────────────────
// ⚠️⚠️ LE DÉFAUT D'UNE MISE À JOUR DE VINTED/LBC/eBAY, et la raison d'être de
// cette passe (Julien : « même s'il y a des mises à jour, plus aucun problème
// dans la récupération »). Le jour où le site renomme la clé de liste
// (`my_orders` → `orders`, `items` → `catalog_items`…), `parsed[cle]` devient
// `undefined`, la capture tombe à 0, et `listePlusRiche` l'ignore EN SILENCE
// (ou l'écrit vide sur un compte neuf). Personne ne sait POURQUOI — c'est
// exactement « rien lu ne vaut pas rien », mais déclenché par une dérive de
// forme au lieu d'une panne.
// ⚠️ ON NE DEVINE PAS UN NOUVEAU PARSER. Le dossier l'interdit : pas de parser
// pour une forme jamais vue (ce serait promettre ce qu'on n'a pas mesuré). On
// rend la dérive BRUYANTE et MESURABLE : si la clé attendue est absente alors
// qu'une AUTRE clé de tête porte une liste NON VIDE, on note
// `forme_inconnue_<type>` + les NOMS des clés de tête (jamais leur contenu) et
// la clé-candidate. La prochaine passe aliasera sur une forme RÉELLEMENT
// mesurée, pas supposée.
// ⚠️ Une réponse légitimement VIDE (clé présente, tableau vide) ne déclenche
// RIEN — sinon la sentinelle crierait au loup sur chaque compte sans vente.
function verifFormeListe(type, parsed, id) {
  try {
    const cle = CLE_LISTE[type];
    if (!cle || !parsed || typeof parsed !== 'object') return;
    if (!Array.isArray(parsed) && Array.isArray(parsed[cle])) {
      // La clé de liste est là : la forme de tête est bonne. Reste à vérifier que
      // les CHAMPS qu'on lit à l'intérieur n'ont pas été renommés sous nos pieds.
      verifChampsListe(type, parsed[cle], id);
      return;
    }
    let cand = null, cles = [];
    if (Array.isArray(parsed)) {
      // Vinted a renvoyé un tableau NU au lieu de `{ <cle>: [...] }`.
      if (parsed.length > 0) cand = '(racine)';
    } else {
      cles = Object.keys(parsed);
      cand = cles.find(k => Array.isArray(parsed[k]) && parsed[k].length > 0) || null;
    }
    if (!cand) return;                            // aucune liste ailleurs : vide légitime, pas une dérive
    noterDiag(`forme_inconnue_${type}`);
    majTampon((buf) => {
      buf.rates[`forme_${type}`] = {
        id: String(id == null ? '' : id).slice(0, 40),
        attendu: cle,
        candidate: String(cand).slice(0, 40),
        cles: cles.slice(0, 20).map(k => String(k).slice(0, 40)),
        at: new Date().toISOString(),
      };
    });
  } catch (_) { /* une sentinelle ne casse jamais la capture */ }
}

// Dérive AU NIVEAU DU CHAMP (la clé de liste est bonne, un champ intérieur a
// changé de nom). Règle anti-fausse-alerte : on ne signale un champ que s'il est
// absent de TOUS les items d'une liste NON VIDE (0/N). Un champ manquant sur un
// item isolé (un brouillon sans prix, un vendeur sans marque) laisse les autres
// items le porter → pas d'alerte. Seul un RENOMMAGE fait disparaître le champ de
// tout le monde d'un coup — et c'est ça, et seulement ça, qu'on veut attraper.
// On ne devine aucun nouveau parser : on rend la dérive bruyante et mesurable
// (le NOM du champ perdu + les noms de clés d'un item), la passe suivante aliase.
function verifChampsListe(type, liste, id) {
  try {
    const champs = CHAMPS_CRITIQUES[type];
    if (!champs || !Array.isArray(liste) || liste.length === 0) return; // vide = légitime
    for (const c of champs) {
      const vu = liste.some(it => it && typeof it === 'object' && it[c] !== undefined && it[c] !== null);
      if (vu) continue;                              // au moins un item le porte : pas une dérive
      noterDiag(`forme_inconnue_champ_${type}`);
      majTampon((buf) => {
        buf.rates[`forme_champ_${type}`] = {
          id: String(id == null ? '' : id).slice(0, 40),
          champ: c,                                  // le champ disparu (un nom, pas une valeur)
          n: liste.length,
          cles: Object.keys(liste[0] || {}).slice(0, 20).map(k => String(k).slice(0, 40)),
          at: new Date().toISOString(),
        };
      });
      return;                                        // un champ perdu suffit à alerter
    }
  } catch (_) { /* une sentinelle ne casse jamais la capture */ }
}

// Dérive sur une capture OBJET (pas une liste) : une TRANSACTION, une
// CONVERSATION. Un renommage du champ qu'on lit casse EN SILENCE la preuve de
// vente, les dates de versement (« vendue → retirée ») ou la messagerie (5.135).
// ⚠️ Même prudence que la liste : on ne juge QUE si l'objet métier est clairement
// une vraie réponse (≥ 3 clés) mais que le champ LU a disparu. Test de PRÉSENCE
// de clé : un renommage fait disparaître `messages`/`status`, une valeur vide
// (`messages: []`, `status: 0`) garde la clé → aucune fausse alerte. Un objet
// maigre/raté n'est pas jugé (mieux vaut un blanc qu'un faux). On ne devine aucun
// parser : on note le NOM du champ perdu + les clés de l'objet, jamais une valeur.
const FORME_OBJET = {
  // la messagerie et le moteur d'offres lisent (p.conversation||p).messages
  conversation: { objet: (p) => (p.conversation || p), champ: 'messages', ok: (o) => Array.isArray(o.messages) },
  // la preuve de vente, les versements et « vendue → retirée » lisent p.transaction.status
  transaction:  { objet: (p) => p.transaction, champ: 'status', ok: (o) => ('status' in o) },
  // le coffre ET la capture photo passive (Leboncoin/eBay) lisent (p.item||p).photos
  item:         { objet: (p) => (p.item || p), champ: 'photos', ok: (o) => Array.isArray(o.photos) },
};
function verifFormeObjet(type, parsed, id) {
  try {
    const r = FORME_OBJET[type];
    if (!r || !parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return;
    const o = r.objet(parsed);
    if (!o || typeof o !== 'object' || Object.keys(o).length < 3) return; // objet maigre : pas un jugement de forme
    if (r.ok(o)) return;                                                   // champ présent : rien à signaler
    noterDiag(`forme_inconnue_champ_${type}`);
    majTampon((buf) => {
      buf.rates[`forme_champ_${type}`] = {
        id: String(id == null ? '' : id).slice(0, 40),
        champ: r.champ,
        cles: Object.keys(o).slice(0, 20).map(k => String(k).slice(0, 40)),
        at: new Date().toISOString(),
      };
    });
  } catch (_) { /* une sentinelle ne casse jamais la capture */ }
}

// ══ 5.357 (11 nov., validé par Julien) — LA FORME DES RÉPONSES DE VINTED ══════
// « Alerte si Vinted change sa façon de répondre. » Les sentinelles ci-dessus
// NOTENT une dérive, puis la capture est rangée quand même : un prix devenu un
// nombre (au lieu de `{amount}`), un `status_title` devenu un objet… était rangé
// tel quel par-dessus une bonne lecture, et l'app lisait `0 €` ou « pas une
// vente » sans rien dire. Désormais, pour chaque réponse rangée, une empreinte de
// FORME (noms de champs et types, jamais une valeur) est comparée à la forme
// connue, sur les seuls champs dont dépend une règle :
//   · forme inattendue (type changé, ou champ OBLIGATOIRE disparu de toute la
//     liste) ⇒ RIEN n'est écrit (la bonne lecture d'avant reste : `listePlusRiche`
//     ne voit même pas passer la douteuse), la forme vue est rangée dans
//     `harvest_{uid}_forme_inconnue` (sans valeur personnelle) et l'app le dit
//     (« Vinted a changé sa page des ventes : VRM ne la lit plus, on corrige ») ;
//   · un champ FACULTATIF simplement absent ne déclenche jamais rien ;
//   · un seul article d'une autre forme parmi des bons ne déclenche rien (Vinted
//     varie d'un article à l'autre) : il faut qu'AUCUN ne porte la forme connue ;
//   · la forme revenue (ou lue par une version corrigée) efface l'alerte.
// Règle : [champ, genre, obligatoire]. Genres : `id` (nombre ou texte court),
// `texte`, `nombre` (ou chiffres en texte), `booleen`, `prix` (objet avec
// `amount`), `liste`.
const GENRES_FORME = {
  id: (v) => (typeof v === 'number' && isFinite(v)) || (typeof v === 'string' && /^[\w-]{1,64}$/.test(v)),
  texte: (v) => typeof v === 'string',
  nombre: (v) => (typeof v === 'number' && isFinite(v)) || (typeof v === 'string' && /^-?\d+(?:\.\d+)?$/.test(v)),
  booleen: (v) => typeof v === 'boolean',
  prix: (v) => !!(v && typeof v === 'object' && !Array.isArray(v) && (typeof v.amount === 'string' || typeof v.amount === 'number')),
  liste: (v) => Array.isArray(v),
};
const CHAMPS_COMMANDE = [['transaction_id', 'id', 1], ['title', 'texte', 0], ['price', 'prix', 0], ['transaction_user_status', 'texte', 0], ['item_id', 'id', 0]];
const REGLES_FORME_VINTED = {
  listings:         { page: 'annonces', liste: 'items', champs: [['id', 'id', 1], ['price', 'prix', 1], ['title', 'texte', 0], ['is_hidden', 'booleen', 0]] },
  orders_sold:      { page: 'ventes', liste: 'my_orders', champs: CHAMPS_COMMANDE },
  orders_purchased: { page: 'achats', liste: 'my_orders', champs: CHAMPS_COMMANDE },
  inbox:            { page: 'messagerie', liste: 'conversations', champs: [['id', 'id', 1]] },
  transaction:      { page: 'ventes', objet: (p) => p.transaction, champs: [['status', 'nombre', 1], ['status_title', 'texte', 0], ['item_id', 'id', 0]] },
  conversation:     { page: 'messagerie', objet: (p) => (p.conversation || p), champs: [['messages', 'liste', 1]] },
  profile:          { page: 'profil', objet: (p) => p.user, champs: [['id', 'id', 1], ['is_account_banned', 'booleen', 0], ['login', 'texte', 0]] },
  // Le porte-monnaie : jugé seulement sur SA forme (`main` ET `escrow`) — le motif
  // « billing » attrape aussi des réponses de tarification, qui ne sont pas jugées.
  billing:          { page: 'porte-monnaie', objet: (p) => p, quand: (o) => 'main' in o && 'escrow' in o, champs: [['main', 'prix', 1], ['escrow', 'prix', 1]] },
};
