async function attendreBordereau(uid, tx) {
  if (!uid || !tx) return { ok: false };
  try { await chrome.storage.local.set({ [BORD_ATTENDU]: { uid: String(uid), tx: String(tx), at: Date.now() } }); } catch (_) {}
  return { ok: true };
}

