  if (String(method || 'POST').toUpperCase() !== 'GET') { noterDiag('ecriture_requete_refusee'); return { status: 0, ok: false, json: null, rienParti: true, sansPage: 'ecriture', ecritureRefusee: true, raison: RAISON_ECRITURE_REQUETE }; }
