  const stop = await garde(uid, acc, { sorte: 'offre', rythme: true }); if (stop) return stop;          // anti-blocage : compte de l'onglet + plafond horaire + pause
  if (quoi !== 'accept' && quoi !== 'reject') return { ok: false, error: 'action inconnue' };
