  if (g.raisons.includes('zero')) return 'un prix de 0 € ou moins ne part jamais';
  const q = g.actuelC != null ? `${e(g.prixC)} au lieu de ${e(g.actuelC)}` : e(g.prixC);
  const pourquoi = [];
