  o.rot = borne(r.rot, -15, 15, 0); o.bright = borne(r.bright, 0.5, 1.5, 1); o.contrast = borne(r.contrast, 0.5, 1.5, 1);
  o.sat = borne(r.sat, 0, 2, 1); o.zoom = borne(r.zoom, 1, 2, 1);
