  const suite = a0 && a0.sorte === sorte && a0.uid === uid && (Date.now() - Number(a0.maj || 0) < ACTION_FRAIS_MS || (serie && a0.serie === serie)) && !(a0.fin && a0.fin.raison === 'arret');
