  const site = plateformeDe(o.url) === 'leboncoin' ? 'leboncoin' : plateformeDe(o.url) === 'vestiaire' ? 'vestiaire' : 'vinted';
  const items = Array.isArray(msg.items) ? msg.items.slice(0, PRIX_CARTE_MAX) : [];
