  if (!Array.isArray(rows)) { noterDiag('prix_attente_lecture_ratee'); return { lu: false }; }
  if (!rows.length) return { lu: true, n: 0, issues: [] };
  const vus = await lirePrixAttVus();
  if (vus === null) return { lu: true, saute: 'stockage' };
