    if (!dem || !fin || t > fin || dem > t + 120000) { await finirPrixAtt(id, moi, d, 'expiree', { code: 'expiree', raison: RAISON_REFUS_PRIX_ATT.expiree }, 'attente'); noterDiag('prix_attente_expiree'); issues.push('expiree'); continue; }
