  if (r && r.pasParti && ['vinted-pause', 'vinted-absent', 'vinted-autre', 'secu-robot', 'verification', 'tout-arrete', 'plafond', 'onglet-vinted', 'compte-bloque'].includes(r.code)) l2.fin = { raison: r.code, at: Date.now() };
